//! The template engine: Jinja with boilersync's `$${ ... }` delimiters.
//!
//! Values are rendered the way the original Python implementation rendered
//! them (`True`/`False` for booleans), so projects generated by either
//! implementation compare equal in `diff` and `push`.

use std::collections::HashSet;
use std::fmt;
use std::path::Path;
use std::sync::Arc;

use minijinja::Environment;
use minijinja::syntax::SyntaxConfig;
use minijinja::value::{Object, Value as JinjaValue};
use serde_json::Value;

use crate::error::Result;

/// Ordered variable map used as the interpolation context.
pub type Context = serde_json::Map<String, Value>;

/// A boolean that renders as Python would (`True` / `False`).
#[derive(Debug)]
struct PyBool(bool);

impl Object for PyBool {
    fn is_true(self: &Arc<Self>) -> bool {
        self.0
    }

    fn render(self: &Arc<Self>, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(if self.0 { "True" } else { "False" })
    }
}

/// Python's `str()` of a JSON value, used for path interpolation and the
/// reverse interpolation performed by `push`.
pub fn py_str(value: &Value) -> String {
    match value {
        Value::Null => "None".to_string(),
        Value::Bool(true) => "True".to_string(),
        Value::Bool(false) => "False".to_string(),
        Value::Number(number) => {
            if let Some(float) = number.as_f64()
                && !number.is_i64()
                && !number.is_u64()
            {
                if float.fract() == 0.0 && float.abs() < 1e16 {
                    return format!("{float:.1}");
                }
                return float.to_string();
            }
            number.to_string()
        }
        Value::String(text) => text.clone(),
        other => other.to_string(),
    }
}

fn to_jinja(value: &Value) -> JinjaValue {
    match value {
        Value::Bool(flag) => JinjaValue::from_object(PyBool(*flag)),
        Value::Array(items) => JinjaValue::from(items.iter().map(to_jinja).collect::<Vec<_>>()),
        Value::Object(map) => JinjaValue::from(
            map.iter().map(|(key, value)| (key.clone(), to_jinja(value))).collect::<std::collections::BTreeMap<_, _>>(),
        ),
        Value::Null => JinjaValue::from(()),
        Value::Number(number) => {
            if let Some(int) = number.as_i64() {
                JinjaValue::from(int)
            } else if let Some(uint) = number.as_u64() {
                JinjaValue::from(uint)
            } else {
                JinjaValue::from(number.as_f64().unwrap_or(0.0))
            }
        }
        Value::String(text) => JinjaValue::from(text.as_str()),
    }
}

fn context_value(context: &Context) -> JinjaValue {
    to_jinja(&Value::Object(context.clone()))
}

/// A Jinja environment configured with boilersync's delimiters.
pub fn environment() -> Environment<'static> {
    let mut env = Environment::new();
    let syntax = SyntaxConfig::builder()
        .block_delimiters("$${%", "%}")
        .variable_delimiters("$${", "}")
        .comment_delimiters("$${#", "#}")
        .keep_trailing_newline(true)
        .build()
        .expect("valid boilersync template syntax");
    env.set_syntax(syntax);
    // Python string, list and dict methods (`$${name_snake.upper()}`), as
    // templates written for Jinja2 use them.
    env.set_unknown_method_callback(minijinja_contrib::pycompat::unknown_method_callback);
    env
}

/// Render a template string with `context`.
pub fn render_string(template: &str, context: &Context) -> Result<String> {
    let env = environment();
    Ok(env.render_str(template, context_value(context))?)
}

/// Render every string inside a metadata value, recursing into lists and objects.
pub fn render_value(value: &Value, context: &Context) -> Result<Value> {
    Ok(match value {
        Value::String(text) => Value::String(render_string(text, context)?),
        Value::Array(items) => {
            Value::Array(items.iter().map(|item| render_value(item, context)).collect::<Result<_>>()?)
        }
        Value::Object(map) => Value::Object(
            map.iter().map(|(key, child)| Ok((key.clone(), render_value(child, context)?))).collect::<Result<_>>()?,
        ),
        other => other.clone(),
    })
}

/// Variable names a template string reads from its context. Unparsable
/// content yields no variables, like the original `meta` scan.
pub fn undeclared_variables(content: &str) -> HashSet<String> {
    let env = environment();
    match env.template_from_str(content) {
        Ok(template) => template.undeclared_variables(false),
        Err(_) => HashSet::new(),
    }
}

/// Render `file_path` in place. Files that are not valid UTF-8 or that fail to
/// render (for example stray `$${` text that is not template syntax) are left
/// untouched, matching the original behaviour.
pub fn render_file_in_place(file_path: &Path, context: &Context) -> Result<()> {
    let Some(parent) = file_path.parent() else { return Ok(()) };
    let Some(name) = file_path.file_name().and_then(|n| n.to_str()) else { return Ok(()) };
    let mut env = environment();
    // A plain file loader: minijinja's path loader refuses dot-files such as
    // `.python-version`, which templates do render.
    let parent = parent.to_path_buf();
    env.set_loader(move |name: &str| -> std::result::Result<Option<String>, minijinja::Error> {
        if name.contains("..") {
            return Ok(None);
        }
        match std::fs::read_to_string(parent.join(name)) {
            Ok(text) => Ok(Some(text)),
            Err(err) if err.kind() == std::io::ErrorKind::NotFound => Ok(None),
            Err(err) => Err(minijinja::Error::new(minijinja::ErrorKind::InvalidOperation, err.to_string())),
        }
    });
    let rendered = env.get_template(name).and_then(|template| template.render(context_value(context)));
    match rendered {
        Ok(text) => std::fs::write(file_path, text).map_err(|e| crate::error::Error::io(file_path, e)),
        Err(err) => {
            log::debug!("Leaving {} unrendered: {err}", file_path.display());
            Ok(())
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn context(value: Value) -> Context {
        match value {
            Value::Object(map) => map,
            _ => unreachable!(),
        }
    }

    #[test]
    fn renders_with_custom_delimiters_and_python_booleans() {
        let ctx = context(json!({"name_snake": "demo", "flag": true, "off": false, "n": 3, "f": 1.5}));
        assert_eq!(
            render_string("$${name_snake} $${flag} $${off} $${n} $${f} {{ plain }}\n", &ctx).unwrap(),
            "demo True False 3 1.5 {{ plain }}\n"
        );
        assert_eq!(render_string("$${% if flag %}yes$${% endif %}$${% if off %}no$${% endif %}", &ctx).unwrap(), "yes");
    }

    #[test]
    fn supports_python_string_methods() {
        let ctx = context(json!({"name_snake": "demo_app"}));
        assert_eq!(
            render_string("$${name_snake.upper()}_TOKEN $${name_snake.replace('_', '-')}", &ctx).unwrap(),
            "DEMO_APP_TOKEN demo-app"
        );
    }

    #[test]
    fn renders_dot_files_in_place() {
        let tmp = tempfile::tempdir().unwrap();
        let file = tmp.path().join(".python-version");
        std::fs::write(&file, "$${python_version}\n").unwrap();
        render_file_in_place(&file, &context(json!({"python_version": "3.12"}))).unwrap();
        assert_eq!(std::fs::read_to_string(&file).unwrap(), "3.12\n");
        // Files that are not UTF-8 are left alone.
        let binary = tmp.path().join("image.png");
        std::fs::write(&binary, [0x89, b'P', b'N', b'G', 0xff, 0xfe]).unwrap();
        render_file_in_place(&binary, &Context::new()).unwrap();
        assert_eq!(std::fs::read(&binary).unwrap(), [0x89, b'P', b'N', b'G', 0xff, 0xfe]);
    }

    #[test]
    fn finds_undeclared_variables_only_at_top_level() {
        let found = undeclared_variables(
            "$${a} $${% if b %}$${c}$${% endif %} $${% for item in items %}$${item.name}$${% endfor %}",
        );
        let mut found: Vec<_> = found.into_iter().collect();
        found.sort();
        assert_eq!(found, ["a", "b", "c", "items"]);
        assert!(undeclared_variables("$${% if %}").is_empty());
    }

    #[test]
    fn py_str_matches_python_formatting() {
        assert_eq!(py_str(&json!(true)), "True");
        assert_eq!(py_str(&json!(1.0)), "1.0");
        assert_eq!(py_str(&json!(2.75)), "2.75");
        assert_eq!(py_str(&json!(42)), "42");
        assert_eq!(py_str(&json!("x")), "x");
        assert_eq!(py_str(&Value::Null), "None");
    }
}
